#include <cstddef>
#include <stdexcept>
#include <vector>

struct EventNode {
    int code;
    const EventNode* next;
};

bool IsEventPalindrome(const EventNode* head) {
    // 1. 주기 검증: 순환 리스트는 끝이 없으므로 거부한다.
    const EventNode* slow = head;
    const EventNode* fast = head;
    while (fast != nullptr && fast->next != nullptr) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) {
            throw std::invalid_argument("cyclic list");
        }
    }

    // 2. 길이 검증: 허용된 노드 수를 넘으면 원본을 건드리지 않고 실패한다.
    const std::size_t kMaxNodes = 100000;
    std::size_t length = 0;
    for (const EventNode* p = head; p != nullptr; p = p->next) {
        if (length == kMaxNodes) {
            throw std::invalid_argument("too many nodes");
        }
        ++length;
    }

    // 3. 앞 절반만 저장한 뒤 뒤 절반을 반대 순서로 비교한다.
    std::vector<int> firstHalf;
    firstHalf.reserve(length / 2);
    const EventNode* current = head;
    for (std::size_t i = 0; i < length / 2; ++i) {
        firstHalf.push_back(current->code);
        current = current->next;
    }
    if (length % 2 != 0) {
        current = current->next;  // 홀수 길이의 중앙 이벤트는 비교에서 제외한다.
    }
    for (std::size_t i = 0; i < length / 2; ++i) {
        if (firstHalf[length / 2 - 1 - i] != current->code) {
            return false;
        }
        current = current->next;
    }
    return true;
}

#include <cassert>
#include <climits>
#include <stdexcept>
#include <vector>

// 위 정답 코드의 EventNode, IsEventPalindrome 뒤에 이어 붙여 사용.
std::vector<EventNode> Build(const std::vector<int>& values) {
    std::vector<EventNode> nodes(values.size());
    for (std::size_t i = 0; i < values.size(); ++i) {
        nodes[i].code = values[i];
        nodes[i].next = i + 1 < values.size() ? &nodes[i + 1] : nullptr;
    }
    return nodes;
}

int main() {
    std::vector<EventNode> a = Build({5, 7, 3, 7, 5});
    assert(IsEventPalindrome(&a[0]));
    std::vector<EventNode> b = Build({1, 2, 1, 2});
    assert(!IsEventPalindrome(&b[0]));
    std::vector<EventNode> c = Build({INT_MIN, INT_MAX, INT_MIN});
    assert(IsEventPalindrome(&c[0]));
    assert(IsEventPalindrome(nullptr));

    EventNode cycle = {7, nullptr};
    cycle.next = &cycle;
    bool rejected = false;
    try { IsEventPalindrome(&cycle); }
    catch (const std::invalid_argument&) { rejected = true; }
    assert(rejected);
}
